import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { dashboardAPI } from '../services/api';

const HistoryPage = () => {
  const { balance } = useAuth();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // all, openings, upgrades, rewards

  useEffect(() => {
    const fetchHistory = async () => {
      try {
        const historyResponse = await dashboardAPI.getHistory();
        setHistory(historyResponse.data);
      } catch (error) {
        console.error('Error fetching history:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchHistory();
  }, []);

  const filteredHistory = history.filter(item => {
    if (filter === 'all') return true;
    if (filter === 'openings') return item.type === 'opening';
    if (filter === 'upgrades') return item.type === 'upgrade';
    if (filter === 'rewards') return item.type === 'reward';
    return false;
  });

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">History</h1>
      <div className="alert alert-info">
        Virtual currency — no real-money value
      </div>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>

      {/* History Filters */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="btn-group btn-group-toggle" data-toggle="buttons">
            <label className={`btn btn-outline-primary ${filter === 'all' ? 'active' : ''}`}>
              <input type="radio" name="options" checked={filter === 'all'}> All </input>
            </label>
            <label className={`btn btn-outline-primary ${filter === 'openings' ? 'active' : ''}`}>
              <input type="radio" name="options" checked={filter === 'openings'}> Openings </input>
            </label>
            <label className={`btn btn-outline-primary ${filter === 'upgrades' ? 'active' : ''}`}>
              <input type="radio" name="options" checked={filter === 'upgrades'}> Upgrades </input>
            </label>
            <label className={`btn btn-outline-primary ${filter === 'rewards' ? 'active' : ''}`}>
              <input type="radio" name="options" checked={filter === 'rewards'}> Rewards </input>
            </label>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="table-responsive">
        <table className="table table-hover align-middle">
          <thead className="table-dark">
            <tr>
              <th>Date</th>
              <th>Type</th>
              <th>Details</th>
              <th>Balance Before</th>
              <th>Balance After</th>
            </tr>
          </thead>
          <tbody>
            {filteredHistory.length > 0 ? (
              filteredHistory.map(item => (
                <tr key={item.id}>
                  <td>{new Date(item.timestamp).toLocaleString()}</td>
                  <td>
                    <span className={`badge bg-${item.type === 'opening' ? 'info' : item.type === 'upgrade' ? 'warning' : 'success'}`}>
                      {item.type.charAt(0).toUpperCase() + item.type.slice(1)}
                    </span>
                  </td>
                  <td>
                    {item.type === 'opening' && (
                      <>
                        Opened <strong>{item.caseName}</strong><br/>
                        Received: <span className={`text-${item.itemRarity === 'rare-special' ? 'warning' : item.itemRarity.toLowerCase()}`}>
                          <strong>{item.itemName}</strong>
                        </span>
                      </>
                    )}
                    {item.type === 'upgrade' && (
                      <>
                        Upgraded <strong>{item.inputCount}</strong> items<br/>
                        Received: <span className={`text-${item.outputRarity === 'rare-special' ? 'warning' : item.outputRarity.toLowerCase()}`}>
                          <strong>{item.outputName}</strong>
                        </span>
                      </>
                    )}
                    {item.type === 'reward' && (
                      <>
                        Daily Reward:<br/>
                        <strong>+{item.rewardAmount} €</strong>
                      </>
                    )}
                  </td>
                  <td>{item.balanceBefore.toLocaleString()} €</td>
                  <td>{item.balanceAfter.toLocaleString()} €</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="text-center text-muted py-4">
                  No history yet
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default HistoryPage;
